```sql
CREATE OR REPLACE VIEW ent AS SELECT entity_id, name, coalesce(nullif(lei,''),entity_id) k, country, entity_type, nullif(parent_id,'') parent_id, source_system FROM entities WHERE source_system<>'QA';
```

```sql
CREATE OR REPLACE VIEW canon AS SELECT k, coalesce(min(entity_id) FILTER (WHERE source_system='RATINGS'), min(entity_id)) cid, coalesce(max(country) FILTER (WHERE source_system='RESEARCH'), max(country)) country, max(parent_id) FILTER (WHERE source_system='RATINGS') pid, max(entity_type) etype FROM ent GROUP BY k;
```

```sql
CREATE OR REPLACE VIEW ra AS SELECT a.*, e.k FROM rating_actions a JOIN ent e ON e.entity_id=a.rated_id;
```

```sql
CREATE OR REPLACE VIEW st AS SELECT * FROM (SELECT *, row_number() OVER (PARTITION BY k,rating_type,ccy_basis ORDER BY date DESC, action_id DESC) rn FROM ra WHERE date<='2026-10-01' AND rating_type IN ('LTIDR','STIDR')) WHERE rn=1;
```

```sql
SELECT (SELECT count(DISTINCT k) FROM ent) q37, (SELECT count(DISTINCT k) FROM st WHERE rating_type='LTIDR' AND rating<>'WD') q9, (SELECT count(DISTINCT k) FROM st JOIN canon USING(k) WHERE rating_type='LTIDR' AND rating<>'WD' AND country='GB') q40, (SELECT count(DISTINCT k) FROM canon WHERE country='LU') q43;
```

```sql
CREATE OR REPLACE VIEW edges AS SELECT c.k, p.k pk FROM canon c JOIN ent p ON p.entity_id=c.pid;
```

```sql
CREATE OR REPLACE VIEW anc AS WITH RECURSIVE u(k,a,l) AS (SELECT k,k,0 FROM canon UNION ALL SELECT u.k,e.pk,l+1 FROM u JOIN edges e ON e.k=u.a) SELECT * FROM u;
```

```sql
SELECT r.cid, r.k, (SELECT name FROM ent WHERE entity_id=r.cid) nm, count(*) n, count(*) FILTER (WHERE a.l=3) l3 FROM anc a JOIN canon r ON r.k=a.a WHERE r.cid IN ('E5001','E5059') OR r.cid IN (SELECT entity_id FROM entities WHERE name ILIKE 'Rotam Group%' OR name ILIKE 'Wonod Group%' OR name ILIKE 'Vesol Group%' OR name ILIKE 'Halden Group%' OR name ILIKE 'Northwind Hold%') GROUP BY ALL;
```

```sql
SELECT a.l, (SELECT cid FROM canon WHERE k=a.a) anc_id, (SELECT name FROM ent WHERE entity_id=(SELECT cid FROM canon WHERE k=a.a)) nm, a.k, (SELECT name FROM ent WHERE entity_id=(SELECT cid FROM canon WHERE k=a.k)) src FROM anc a WHERE a.k IN (SELECT k FROM ent WHERE name ILIKE 'Cerid Rosor%' OR name ILIKE 'Belir Mining%' OR name ILIKE 'Rotam Group%' OR entity_id IN ('E5011','E5056','E5133','E5145','E5090','E5108','E11','E04')) ORDER BY a.k, a.l;
```

